import random
import re


def _lines(text: str) -> list[str]:
    text = text.replace("\r\n", "\n")
    if text.endswith("\n"):
        text = text[:-1]
    return text.split("\n")


def _valid_rows(rows: list[str], size: int) -> bool:
    return len(rows) == size and all(
        len(row) == size and row.count("#") + row.count(".") == size
        for row in rows
    )


def _parse_input(inp: str) -> list[str] | None:
    header, *rows = _lines(inp)
    if re.fullmatch(r"\+?[0-9]+", header) is None:
        return None
    digits = header.lstrip("+").lstrip("0")
    if not digits or len(digits) > 4:
        return None
    size = int(digits)
    if not 2 <= size <= 3000 or size % 2 or not _valid_rows(rows, size):
        return None
    return rows


def _format_input(rows: list[str]) -> str:
    return str(len(rows)) + "\n" + "\n".join(rows) + "\n"


def _random_rows(rng: random.Random, size: int) -> list[str]:
    colors = str.maketrans("01", ".#")
    return [
        format(rng.getrandbits(size), f"0{size}b").translate(colors)
        for _ in range(size)
    ]


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    fixed = [
        ["#.", ".."],
        ["#..#", "..#.", "....", ".#.."],
        ["#.#.#.", ".#.#.#", "#.#.#.", ".#.#.#", "#.#.#.", ".#.#.#"],
        ["........"] * 3 + ["...#...."] + ["........"] * 4,
        ["##", "##"],
        ["..", ".."],
    ]
    inputs = [_format_input(rows) for rows in fixed[:n]]
    while len(inputs) < n:
        size = rng.choice((2, 4, 6, 8))
        inputs.append(_format_input(_random_rows(rng, size)))
    return inputs


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    dense = _format_input(_random_rows(rng, 3000))
    size = 2998
    sparse_rows = []
    for _ in range(size):
        column = rng.randrange(size)
        sparse_rows.append("." * column + "#" + "." * (size - 1 - column))
    return [dense, _format_input(sparse_rows)]


def _quarter_turn_counts(
    rows: list[str], row: int, column: int, last: int
) -> int:
    return (
        (rows[row][column] == "#")
        + (rows[column][last - row] == "#")
        + (rows[last - row][last - column] == "#")
        + (rows[last - column][row] == "#")
    )


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    before = _parse_input(inp)
    if before is None:
        return [("POST-1", "Input does not meet the grid format or bounds.")]
    after = _lines(out)
    size = len(before)
    if not _valid_rows(after, size):
        return [("POST-2", f"Expected {size} rows of {size} characters from '#.'.")]
    last = size - 1
    for row in range(size // 2):
        for column in range(size // 2):
            if _quarter_turn_counts(before, row, column, last) != (
                _quarter_turn_counts(after, row, column, last)
            ):
                return [
                    (
                        "POST-3",
                        f"Black-cell count changed among the quarter-turn "
                        f"positions of ({row + 1}, {column + 1}).",
                    )
                ]
    return []


