def reference_small(inp: str) -> str | None:
    rows = _parse_input(inp)
    if rows is None or len(rows) > 8:
        return None
    size = len(rows)
    current = [list(row) for row in rows]
    for i in range(1, size // 2 + 1):
        next_grid = [row[:] for row in current]
        for x in range(i, size + 2 - i):
            for y in range(i, size + 2 - i):
                next_grid[y - 1][size - x] = current[x - 1][y - 1]
        current = next_grid
    return "\n".join("".join(row) for row in current) + "\n"
